package com.foodordering.order; import com.foodordering.security.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/orders") public class OrderController {private final OrderService service;OrderController(OrderService s){service=s;}@PostMapping @ResponseStatus(HttpStatus.CREATED) OrderResponse create(@Valid @RequestBody CreateOrderRequest x,Authentication a){return service.create(x,SecuritySupport.principal(a));}@GetMapping("/{id}") OrderResponse get(@PathVariable Long id,Authentication a){return service.get(id,SecuritySupport.principal(a));}@GetMapping("/customer/{id}") List<OrderResponse> customer(@PathVariable Long id,Authentication a){return service.customer(id,SecuritySupport.principal(a));}@PutMapping("/{id}/cancel") OrderResponse cancel(@PathVariable Long id,Authentication a){return service.cancel(id,SecuritySupport.principal(a));}@GetMapping Page<OrderResponse> all(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){return service.all(PageRequest.of(Math.max(0,page),Math.min(100,Math.max(1,size)),Sort.by(Sort.Direction.DESC,"orderDate")));}}
